-- GENERATED by scripts/generate-seed.mjs — refreshes lesson content of missions edited after the first seed.
-- Safe to run more than once. Run it only if you already ran 003 before the content was extended.

do $r$
declare v_id uuid;
begin
  select id into v_id from public.missions where slug = 'waste';
  if v_id is null then raise exception 'mission waste not found - run 003 first'; end if;
  delete from public.mission_steps  where mission_id = v_id;
  delete from public.game_questions where mission_id = v_id;
  -- re-validates the whole mission (Hausa + English) if it is published
  update public.missions set updated_at = now() where id = v_id;
end $r$;

